public class Point {
    private int x;
    private int y;

    public Point(int x, int y) {
        this.x = x;
        this.y = y;
    }

    public int getX() { return x; }
    public int getY() { return y; }
}

Point p = new Point(3, 4);
System.out.println(p.getX() + p.getY());   // 7
